import React, { useEffect, useState } from "react";
import { api, errMsg } from "@/lib/api";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Progress } from "@/components/ui/progress";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Plus, Minus, Trash2, Boxes, Pencil } from "lucide-react";
import { toast } from "sonner";

export default function Inventory() {
  const [items, setItems] = useState([]);
  const [suppliers, setSuppliers] = useState([]);
  const [open, setOpen] = useState(false);
  const empty = { name: "", category: "Produce", unit: "kg", current_qty: 0, par_level: 0, reorder_qty: 0, cost_per_unit: 0, supplier_id: "" };
  const [form, setForm] = useState(empty);
  const [editId, setEditId] = useState(null);

  const load = () => {
    api.get("/inventory").then((r) => setItems(r.data)).catch(() => {});
    api.get("/suppliers").then((r) => setSuppliers(r.data)).catch(() => {});
  };
  useEffect(() => { load(); }, []);

  const adjust = async (item, delta) => {
    const newQty = Math.max(0, Number(item.current_qty) + delta);
    try {
      const { data } = await api.put(`/inventory/${item.id}`, { current_qty: newQty });
      if (data.auto_order?.triggered) toast.warning(`${item.name} below par → added to supplier order`);
      load();
    } catch (e) { toast.error(errMsg(e)); }
  };

  const save = async () => {
    if (!form.name) return toast.error("Add a name");
    const payload = { ...form, current_qty: Number(form.current_qty), par_level: Number(form.par_level), reorder_qty: Number(form.reorder_qty), cost_per_unit: Number(form.cost_per_unit) };
    try {
      if (editId) await api.put(`/inventory/${editId}`, payload);
      else await api.post("/inventory", payload);
      toast.success("Saved"); setOpen(false); setForm(empty); setEditId(null); load();
    } catch (e) { toast.error(errMsg(e)); }
  };

  const edit = (i) => { setForm({ ...empty, ...i }); setEditId(i.id); setOpen(true); };
  const del = async (id) => { await api.delete(`/inventory/${id}`); load(); };
  const supName = (id) => suppliers.find((s) => s.id === id)?.name || "—";

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><Boxes className="w-7 h-7 text-primary" /> Inventory &amp; Stock</h1>
          <p className="text-muted-foreground">Below-par items are auto-drafted into supplier orders.</p>
        </div>
        <Dialog open={open} onOpenChange={(v) => { setOpen(v); if (!v) { setForm(empty); setEditId(null); } }}>
          <DialogTrigger asChild><Button data-testid="add-inventory-btn"><Plus className="w-4 h-4 mr-1" /> Add item</Button></DialogTrigger>
          <DialogContent>
            <DialogHeader><DialogTitle>{editId ? "Edit item" : "Add stock item"}</DialogTitle></DialogHeader>
            <div className="space-y-3">
              <div><Label>Name</Label><Input data-testid="inv-name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
              <div className="grid grid-cols-2 gap-3">
                <div><Label>Category</Label><Input value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} /></div>
                <div><Label>Unit</Label><Input value={form.unit} onChange={(e) => setForm({ ...form, unit: e.target.value })} /></div>
              </div>
              <div className="grid grid-cols-3 gap-3">
                <div><Label>On hand</Label><Input type="number" data-testid="inv-qty" value={form.current_qty} onChange={(e) => setForm({ ...form, current_qty: e.target.value })} /></div>
                <div><Label>Par level</Label><Input type="number" data-testid="inv-par" value={form.par_level} onChange={(e) => setForm({ ...form, par_level: e.target.value })} /></div>
                <div><Label>Reorder qty</Label><Input type="number" value={form.reorder_qty} onChange={(e) => setForm({ ...form, reorder_qty: e.target.value })} /></div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div><Label>Cost / unit</Label><Input type="number" value={form.cost_per_unit} onChange={(e) => setForm({ ...form, cost_per_unit: e.target.value })} /></div>
                <div><Label>Supplier</Label>
                  <select data-testid="inv-supplier" className="w-full h-10 rounded-md border px-3 mt-1 bg-background" value={form.supplier_id} onChange={(e) => setForm({ ...form, supplier_id: e.target.value })}>
                    <option value="">— none —</option>
                    {suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                </div>
              </div>
            </div>
            <DialogFooter><Button onClick={save} data-testid="save-inventory-btn">Save</Button></DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      <div className="grid gap-3">
        {items.map((i) => {
          const pct = Math.min(100, (Number(i.current_qty) / (Number(i.par_level) || 1)) * 100);
          const low = Number(i.current_qty) <= Number(i.par_level);
          return (
            <Card key={i.id} className="p-4 hoverable" data-testid={`inv-row-${i.id}`}>
              <div className="flex items-center gap-4 flex-wrap">
                <div className="flex-1 min-w-[180px]">
                  <div className="flex items-center gap-2">
                    <h3 className="font-semibold">{i.name}</h3>
                    <Badge variant="secondary" className="text-[10px]">{i.category}</Badge>
                    {low && <Badge className="bg-rose-100 text-rose-700 hover:bg-rose-100 text-[10px]">Below par</Badge>}
                  </div>
                  <p className="text-xs text-muted-foreground mt-0.5">{supName(i.supplier_id)}</p>
                  <div className="mt-2 flex items-center gap-2">
                    <Progress value={pct} className={`h-2 flex-1 ${low ? "[&>div]:bg-rose-500" : "[&>div]:bg-emerald-500"}`} />
                    <span className="text-xs font-mono w-24 text-right">{i.current_qty}/{i.par_level} {i.unit}</span>
                  </div>
                </div>
                <div className="flex items-center gap-1.5">
                  <Button size="icon" variant="outline" onClick={() => adjust(i, -1)} data-testid={`dec-${i.id}`}><Minus className="w-4 h-4" /></Button>
                  <Button size="icon" variant="outline" onClick={() => adjust(i, 1)} data-testid={`inc-${i.id}`}><Plus className="w-4 h-4" /></Button>
                  <Button size="icon" variant="ghost" onClick={() => edit(i)}><Pencil className="w-4 h-4" /></Button>
                  <Button size="icon" variant="ghost" onClick={() => del(i.id)} className="text-rose-500"><Trash2 className="w-4 h-4" /></Button>
                </div>
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}
