import React, { useEffect, useState } from "react";
import { api, errMsg } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Plus, CalendarDays, Trash2, Clock } from "lucide-react";
import { toast } from "sonner";

function weekDates(offset = 0) {
  const now = new Date();
  const day = (now.getDay() + 6) % 7;
  const monday = new Date(now); monday.setDate(now.getDate() - day + offset * 7);
  return Array.from({ length: 7 }, (_, i) => { const d = new Date(monday); d.setDate(monday.getDate() + i); return d; });
}

export default function Roster() {
  const { user, isManager } = useAuth();
  const [rosters, setRosters] = useState([]);
  const [staff, setStaff] = useState([]);
  const [offset, setOffset] = useState(0);
  const [open, setOpen] = useState(false);
  const empty = { staff_id: "", staff_name: "", date: "", start: "09:00", end: "17:00", notes: "" };
  const [form, setForm] = useState(empty);

  const load = () => {
    api.get("/rosters").then((r) => setRosters(r.data)).catch(() => {});
    if (isManager) api.get("/staff").then((r) => setStaff(r.data.filter((s) => s.active))).catch(() => {});
  };
  useEffect(() => { load(); }, []);

  const dates = weekDates(offset);
  const iso = (d) => d.toISOString().slice(0, 10);

  const save = async () => {
    if (!form.staff_id || !form.date) return toast.error("Pick staff and date");
    const st = staff.find((s) => s.id === form.staff_id);
    try { await api.post("/rosters", { ...form, staff_name: st?.name }); toast.success("Shift added"); setOpen(false); setForm(empty); load(); } catch (e) { toast.error(errMsg(e)); }
  };
  const del = async (id) => { await api.delete(`/rosters/${id}`); load(); };

  const visible = isManager ? rosters : rosters.filter((r) => r.staff_id === user.id);

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><CalendarDays className="w-7 h-7 text-primary" /> {isManager ? "Roster" : "My Roster"}</h1>
          <p className="text-muted-foreground">Weekly shift schedule.</p>
        </div>
        <div className="flex items-center gap-2">
          <Button variant="outline" size="sm" onClick={() => setOffset(offset - 1)}>‹ Prev</Button>
          <Button variant="outline" size="sm" onClick={() => setOffset(0)}>This week</Button>
          <Button variant="outline" size="sm" onClick={() => setOffset(offset + 1)}>Next ›</Button>
          {isManager && (
            <Dialog open={open} onOpenChange={setOpen}>
              <DialogTrigger asChild><Button data-testid="add-shift-btn"><Plus className="w-4 h-4 mr-1" /> Shift</Button></DialogTrigger>
              <DialogContent>
                <DialogHeader><DialogTitle>Add shift</DialogTitle></DialogHeader>
                <div className="space-y-3">
                  <div><Label>Staff</Label>
                    <select data-testid="shift-staff" className="w-full h-10 rounded-md border px-3 mt-1 bg-background" value={form.staff_id} onChange={(e) => setForm({ ...form, staff_id: e.target.value })}>
                      <option value="">— choose —</option>
                      {staff.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                    </select>
                  </div>
                  <div><Label>Date</Label><Input type="date" data-testid="shift-date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></div>
                  <div className="grid grid-cols-2 gap-3">
                    <div><Label>Start</Label><Input type="time" value={form.start} onChange={(e) => setForm({ ...form, start: e.target.value })} /></div>
                    <div><Label>End</Label><Input type="time" value={form.end} onChange={(e) => setForm({ ...form, end: e.target.value })} /></div>
                  </div>
                </div>
                <DialogFooter><Button onClick={save} data-testid="save-shift-btn">Save</Button></DialogFooter>
              </DialogContent>
            </Dialog>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-7 gap-3">
        {dates.map((d) => {
          const dayShifts = visible.filter((r) => r.date === iso(d));
          const isToday = iso(d) === iso(new Date());
          return (
            <Card key={iso(d)} className={`p-3 min-h-[140px] ${isToday ? "ring-2 ring-primary/40" : ""}`} data-testid={`day-${iso(d)}`}>
              <p className="text-xs font-semibold text-muted-foreground">{d.toLocaleDateString(undefined, { weekday: "short" })}</p>
              <p className="text-lg font-bold">{d.getDate()}</p>
              <div className="space-y-1.5 mt-2">
                {dayShifts.map((s) => (
                  <div key={s.id} className="text-xs bg-accent rounded-lg p-1.5 group" data-testid={`shift-${s.id}`}>
                    <div className="flex items-center justify-between">
                      <span className="font-medium truncate">{s.staff_name}</span>
                      {isManager && <button onClick={() => del(s.id)} className="opacity-0 group-hover:opacity-100 text-rose-500"><Trash2 className="w-3 h-3" /></button>}
                    </div>
                    <span className="flex items-center gap-1 text-muted-foreground"><Clock className="w-3 h-3" />{s.start}–{s.end}</span>
                  </div>
                ))}
              </div>
            </Card>
          );
        })}
      </div>
    </div>
  );
}
