import React, { useEffect, useState } from "react";
import { api, errMsg } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Plus, SprayCan, Trash2 } from "lucide-react";
import { toast } from "sonner";

export default function Cleaning() {
  const { user, isManager } = useAuth();
  const [items, setItems] = useState([]);
  const [open, setOpen] = useState(false);
  const empty = { name: "", area: "", frequency: "daily", done: false, date: new Date().toISOString().slice(0, 10) };
  const [form, setForm] = useState(empty);

  const load = () => api.get("/cleaning").then((r) => setItems(r.data)).catch(() => {});
  useEffect(() => { load(); }, []);

  const toggle = async (t) => { await api.put(`/cleaning/${t.id}`, { done: !t.done, done_by: !t.done ? user.name : "", done_at: !t.done ? new Date().toISOString() : "" }); load(); };
  const save = async () => { if (!form.name) return toast.error("Add a task"); try { await api.post("/cleaning", form); setOpen(false); setForm(empty); load(); } catch (e) { toast.error(errMsg(e)); } };
  const del = async (id) => { await api.delete(`/cleaning/${id}`); load(); };

  const groups = ["daily", "weekly"];
  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><SprayCan className="w-7 h-7 text-primary" /> Cleaning Schedule</h1>
          <p className="text-muted-foreground">Daily &amp; weekly hygiene tasks with sign-off.</p>
        </div>
        {isManager && (
          <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild><Button data-testid="add-cleaning-btn"><Plus className="w-4 h-4 mr-1" /> Add task</Button></DialogTrigger>
            <DialogContent>
              <DialogHeader><DialogTitle>Add cleaning task</DialogTitle></DialogHeader>
              <div className="space-y-3">
                <div><Label>Task</Label><Input data-testid="cleaning-name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Area</Label><Input value={form.area} onChange={(e) => setForm({ ...form, area: e.target.value })} /></div>
                  <div><Label>Frequency</Label>
                    <select className="w-full h-10 rounded-md border px-3 mt-1 bg-background" value={form.frequency} onChange={(e) => setForm({ ...form, frequency: e.target.value })}>
                      <option value="daily">Daily</option><option value="weekly">Weekly</option>
                    </select>
                  </div>
                </div>
              </div>
              <DialogFooter><Button onClick={save} data-testid="save-cleaning-btn">Save</Button></DialogFooter>
            </DialogContent>
          </Dialog>
        )}
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        {groups.map((g) => (
          <Card key={g} className="p-5">
            <h3 className="font-semibold capitalize mb-3">{g} tasks</h3>
            <div className="space-y-2">
              {items.filter((i) => i.frequency === g).map((t) => (
                <div key={t.id} className="flex items-center gap-3 py-2 border-b last:border-0 group" data-testid={`cleaning-${t.id}`}>
                  <Checkbox checked={!!t.done} onCheckedChange={() => toggle(t)} data-testid={`cleaning-check-${t.id}`} />
                  <div className={`flex-1 ${t.done ? "text-muted-foreground" : ""}`}>
                    <span className={`text-sm font-medium ${t.done ? "line-through" : ""}`}>{t.name}</span>
                    {t.area && <Badge variant="secondary" className="ml-2 text-[10px]">{t.area}</Badge>}
                    {t.done && t.done_by && <p className="text-[11px] text-emerald-600 mt-0.5">✓ {t.done_by}</p>}
                  </div>
                  {isManager && <button onClick={() => del(t.id)} className="opacity-0 group-hover:opacity-100 text-slate-400 hover:text-rose-500"><Trash2 className="w-4 h-4" /></button>}
                </div>
              ))}
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}
