import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { api } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import {
  Boxes, AlertTriangle, Truck, ClipboardList, SprayCan, ScanLine, Clock, ArrowRight, CalendarDays
} from "lucide-react";

const StatCard = ({ icon: Icon, label, value, tone = "slate", to }) => {
  const tones = {
    slate: "text-slate-600 bg-slate-100",
    orange: "text-orange-600 bg-orange-100",
    rose: "text-rose-600 bg-rose-100",
    emerald: "text-emerald-600 bg-emerald-100",
    blue: "text-blue-600 bg-blue-100",
  };
  const inner = (
    <Card className="p-5 hoverable h-full" data-testid={`stat-${label.toLowerCase().replace(/[^a-z]+/g, "-")}`}>
      <div className={`w-10 h-10 rounded-xl grid place-items-center mb-3 ${tones[tone]}`}><Icon className="w-5 h-5" /></div>
      <p className="text-3xl font-bold font-mono">{value}</p>
      <p className="text-sm text-muted-foreground mt-0.5">{label}</p>
    </Card>
  );
  return to ? <Link to={to}>{inner}</Link> : inner;
};

export default function Dashboard() {
  const { user, isManager } = useAuth();
  const [stats, setStats] = useState(null);

  useEffect(() => { api.get("/dashboard/stats").then((r) => setStats(r.data)).catch(() => {}); }, []);

  return (
    <div className="space-y-6">
      <div>
        <p className="text-muted-foreground text-sm">{new Date().toLocaleDateString(undefined, { weekday: "long", day: "numeric", month: "long" })}</p>
        <h1 className="text-3xl sm:text-4xl font-bold tracking-tight">Kia ora, {user?.name?.split(" ")[0]} 👋</h1>
      </div>

      {isManager ? (
        <>
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            <StatCard icon={Boxes} label="Stock items" value={stats?.inventory_count ?? "—"} tone="blue" to="/inventory" />
            <StatCard icon={AlertTriangle} label="Low on stock" value={stats?.low_stock ?? "—"} tone="rose" to="/inventory" />
            <StatCard icon={Truck} label="Draft orders" value={stats?.draft_orders ?? "—"} tone="orange" to="/suppliers" />
            <StatCard icon={ScanLine} label="Traced today" value={stats?.traceability_today ?? "—"} tone="emerald" to="/traceability" />
          </div>

          {stats?.low_stock_items?.length > 0 && (
            <Card className="p-5">
              <div className="flex items-center justify-between mb-3">
                <h3 className="font-semibold text-lg flex items-center gap-2"><AlertTriangle className="w-5 h-5 text-rose-500" /> Below par — auto-added to orders</h3>
                <Link to="/suppliers"><Button variant="outline" size="sm" data-testid="view-orders-btn">View orders <ArrowRight className="w-4 h-4 ml-1" /></Button></Link>
              </div>
              <div className="divide-y">
                {stats.low_stock_items.map((i) => (
                  <div key={i.id} className="flex items-center justify-between py-2.5">
                    <span className="font-medium">{i.name}</span>
                    <span className="text-sm font-mono text-rose-600">{i.current_qty} / {i.par_level} {i.unit}</span>
                  </div>
                ))}
              </div>
            </Card>
          )}

          {stats?.use_first?.length > 0 && (
            <Card className="p-5">
              <div className="flex items-center justify-between mb-3">
                <h3 className="font-semibold text-lg flex items-center gap-2"><Clock className="w-5 h-5 text-amber-500" /> Use first — nearest best-before</h3>
                <Link to="/prep"><Button variant="outline" size="sm" data-testid="view-prep-btn">Prep list <ArrowRight className="w-4 h-4 ml-1" /></Button></Link>
              </div>
              <div className="divide-y">
                {stats.use_first.map((i) => (
                  <div key={i.id} className="flex items-center justify-between py-2.5">
                    <span className="font-medium">{i.name}{i.portions ? <span className="text-muted-foreground font-normal text-sm"> · {i.portions} {i.unit} kept</span> : null}</span>
                    <span className="text-sm font-mono text-amber-600">{i.best_before}</span>
                  </div>
                ))}
              </div>
            </Card>
          )}

          <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
            <StatCard icon={ClipboardList} label="Prep to do" value={stats?.prep_open ?? "—"} tone="orange" to="/prep" />
            <StatCard icon={SprayCan} label="Cleaning open" value={stats?.cleaning_open ?? "—"} tone="blue" to="/cleaning" />
          </div>
        </>
      ) : (
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <Link to="/timesheets"><Card className="p-6 hoverable"><Clock className="w-8 h-8 text-orange-500 mb-3" /><h3 className="font-semibold text-lg">Clock in / out</h3><p className="text-sm text-muted-foreground">Record your shift hours</p></Card></Link>
          <Link to="/roster"><Card className="p-6 hoverable"><CalendarDays className="w-8 h-8 text-blue-500 mb-3" /><h3 className="font-semibold text-lg">My roster</h3><p className="text-sm text-muted-foreground">See your upcoming shifts</p></Card></Link>
        </div>
      )}
    </div>
  );
}
