import React, { useEffect, useState } from "react";
import { api, errMsg } from "@/lib/api";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { BarChart3, Plus, Trash2, TrendingUp, Trash } from "lucide-react";
import { toast } from "sonner";
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, Cell } from "recharts";

export default function Analytics() {
  const [summary, setSummary] = useState(null);
  const [sales, setSales] = useState([]);
  const [wastage, setWastage] = useState([]);
  const [openSale, setOpenSale] = useState(false);
  const [openWaste, setOpenWaste] = useState(false);
  const [sale, setSale] = useState({ date: new Date().toISOString().slice(0, 10), amount: "", covers: "", notes: "" });
  const [waste, setWaste] = useState({ date: new Date().toISOString().slice(0, 10), item: "", qty: "", unit: "kg", cost: "", reason: "Expired" });

  const load = () => {
    api.get("/analytics/summary").then((r) => setSummary(r.data)).catch(() => {});
    api.get("/sales").then((r) => setSales(r.data)).catch(() => {});
    api.get("/wastage").then((r) => setWastage(r.data)).catch(() => {});
  };
  useEffect(() => { load(); }, []);

  const saveSale = async () => { try { await api.post("/sales", { ...sale, amount: Number(sale.amount), covers: Number(sale.covers) }); setOpenSale(false); setSale({ date: new Date().toISOString().slice(0, 10), amount: "", covers: "", notes: "" }); load(); toast.success("Sales added"); } catch (e) { toast.error(errMsg(e)); } };
  const saveWaste = async () => { try { await api.post("/wastage", { ...waste, qty: Number(waste.qty), cost: Number(waste.cost) }); setOpenWaste(false); setWaste({ date: new Date().toISOString().slice(0, 10), item: "", qty: "", unit: "kg", cost: "", reason: "Expired" }); load(); toast.success("Wastage logged"); } catch (e) { toast.error(errMsg(e)); } };
  const delSale = async (id) => { await api.delete(`/sales/${id}`); load(); };
  const delWaste = async (id) => { await api.delete(`/wastage/${id}`); load(); };

  const money = (n) => "$" + Number(n || 0).toLocaleString(undefined, { maximumFractionDigits: 0 });

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><BarChart3 className="w-7 h-7 text-primary" /> Sales &amp; Wastage</h1>
        <p className="text-muted-foreground">End-of-month revenue vs food wastage.</p>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        <Card className="p-5"><p className="text-sm text-muted-foreground">This month sales</p><p className="text-2xl font-bold font-mono mt-1 text-emerald-600">{money(summary?.this_month_sales)}</p></Card>
        <Card className="p-5"><p className="text-sm text-muted-foreground">This month wastage</p><p className="text-2xl font-bold font-mono mt-1 text-rose-600">{money(summary?.this_month_wastage)}</p></Card>
        <Card className="p-5"><p className="text-sm text-muted-foreground">Total sales</p><p className="text-2xl font-bold font-mono mt-1">{money(summary?.total_sales)}</p></Card>
        <Card className="p-5"><p className="text-sm text-muted-foreground">Waste %</p><p className="text-2xl font-bold font-mono mt-1">{summary?.waste_pct ?? 0}%</p></Card>
      </div>

      <div className="grid gap-4 lg:grid-cols-2">
        <Card className="p-5">
          <h3 className="font-semibold mb-4 flex items-center gap-2"><TrendingUp className="w-5 h-5 text-primary" /> Sales vs Wastage (6 mo)</h3>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={summary?.series || []}>
              <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
              <XAxis dataKey="month" tick={{ fontSize: 12 }} />
              <YAxis tick={{ fontSize: 12 }} />
              <Tooltip formatter={(v) => money(v)} />
              <Bar dataKey="sales" fill="#059669" radius={[6, 6, 0, 0]} name="Sales" />
              <Bar dataKey="wastage" fill="#E64A19" radius={[6, 6, 0, 0]} name="Wastage" />
            </BarChart>
          </ResponsiveContainer>
        </Card>
        <Card className="p-5">
          <h3 className="font-semibold mb-4 flex items-center gap-2"><Trash className="w-5 h-5 text-rose-500" /> Top wasted items</h3>
          <ResponsiveContainer width="100%" height={280}>
            <BarChart data={summary?.top_wasted || []} layout="vertical">
              <CartesianGrid strokeDasharray="3 3" stroke="#eee" />
              <XAxis type="number" tick={{ fontSize: 12 }} />
              <YAxis dataKey="name" type="category" width={90} tick={{ fontSize: 12 }} />
              <Tooltip formatter={(v) => money(v)} />
              <Bar dataKey="cost" radius={[0, 6, 6, 0]}>
                {(summary?.top_wasted || []).map((_, i) => <Cell key={i} fill={["#E64A19", "#F57C00", "#FBC02D", "#94A3B8", "#CBD5E1", "#E2E8F0"][i]} />)}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </Card>
      </div>

      <Tabs defaultValue="sales">
        <TabsList>
          <TabsTrigger value="sales" data-testid="tab-sales">Sales log</TabsTrigger>
          <TabsTrigger value="wastage" data-testid="tab-wastage">Wastage log</TabsTrigger>
        </TabsList>

        <TabsContent value="sales" className="mt-4 space-y-3">
          <Dialog open={openSale} onOpenChange={setOpenSale}>
            <DialogTrigger asChild><Button data-testid="add-sale-btn"><Plus className="w-4 h-4 mr-1" /> Add sales</Button></DialogTrigger>
            <DialogContent>
              <DialogHeader><DialogTitle>Add sales record</DialogTitle></DialogHeader>
              <div className="space-y-3">
                <div><Label>Date</Label><Input type="date" value={sale.date} onChange={(e) => setSale({ ...sale, date: e.target.value })} /></div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Amount ($)</Label><Input type="number" data-testid="sale-amount" value={sale.amount} onChange={(e) => setSale({ ...sale, amount: e.target.value })} /></div>
                  <div><Label>Covers</Label><Input type="number" value={sale.covers} onChange={(e) => setSale({ ...sale, covers: e.target.value })} /></div>
                </div>
              </div>
              <DialogFooter><Button onClick={saveSale} data-testid="save-sale-btn">Save</Button></DialogFooter>
            </DialogContent>
          </Dialog>
          {sales.map((s) => (
            <Card key={s.id} className="p-3 flex items-center justify-between" data-testid={`sale-${s.id}`}>
              <span className="text-sm">{s.date} · {s.covers} covers</span>
              <div className="flex items-center gap-3"><span className="font-mono font-semibold text-emerald-600">{money(s.amount)}</span><button onClick={() => delSale(s.id)} className="text-slate-400 hover:text-rose-500"><Trash2 className="w-4 h-4" /></button></div>
            </Card>
          ))}
        </TabsContent>

        <TabsContent value="wastage" className="mt-4 space-y-3">
          <Dialog open={openWaste} onOpenChange={setOpenWaste}>
            <DialogTrigger asChild><Button data-testid="add-waste-btn"><Plus className="w-4 h-4 mr-1" /> Log wastage</Button></DialogTrigger>
            <DialogContent>
              <DialogHeader><DialogTitle>Log wastage</DialogTitle></DialogHeader>
              <div className="space-y-3">
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Date</Label><Input type="date" value={waste.date} onChange={(e) => setWaste({ ...waste, date: e.target.value })} /></div>
                  <div><Label>Item</Label><Input data-testid="waste-item" value={waste.item} onChange={(e) => setWaste({ ...waste, item: e.target.value })} /></div>
                </div>
                <div className="grid grid-cols-3 gap-3">
                  <div><Label>Qty</Label><Input type="number" value={waste.qty} onChange={(e) => setWaste({ ...waste, qty: e.target.value })} /></div>
                  <div><Label>Unit</Label><Input value={waste.unit} onChange={(e) => setWaste({ ...waste, unit: e.target.value })} /></div>
                  <div><Label>Cost ($)</Label><Input type="number" data-testid="waste-cost" value={waste.cost} onChange={(e) => setWaste({ ...waste, cost: e.target.value })} /></div>
                </div>
                <div><Label>Reason</Label>
                  <select className="w-full h-10 rounded-md border px-3 mt-1 bg-background" value={waste.reason} onChange={(e) => setWaste({ ...waste, reason: e.target.value })}>
                    {["Expired", "Over-prep", "Spoiled", "Damaged", "Returned"].map((r) => <option key={r}>{r}</option>)}
                  </select>
                </div>
              </div>
              <DialogFooter><Button onClick={saveWaste} data-testid="save-waste-btn">Save</Button></DialogFooter>
            </DialogContent>
          </Dialog>
          {wastage.map((w) => (
            <Card key={w.id} className="p-3 flex items-center justify-between" data-testid={`waste-${w.id}`}>
              <span className="text-sm">{w.date} · {w.item} ({w.qty}{w.unit}) · {w.reason}</span>
              <div className="flex items-center gap-3"><span className="font-mono font-semibold text-rose-600">{money(w.cost)}</span><button onClick={() => delWaste(w.id)} className="text-slate-400 hover:text-rose-500"><Trash2 className="w-4 h-4" /></button></div>
            </Card>
          ))}
        </TabsContent>
      </Tabs>
    </div>
  );
}
