import React, { useEffect, useState } from "react";
import { api, fileUrl, errMsg } from "@/lib/api";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { PhotoUpload } from "@/components/PhotoUpload";
import { Plus, Trash2, Thermometer, ScanLine, Info } from "lucide-react";
import { toast } from "sonner";

const ALLERGENS = ["Gluten", "Dairy", "Egg", "Fish", "Shellfish", "Nuts", "Peanuts", "Soy", "Sesame", "Celery", "Mustard", "Sulphites"];

export default function Traceability() {
  const [items, setItems] = useState([]);
  const [open, setOpen] = useState(false);
  const empty = { type: "Prep", item_name: "", date: new Date().toISOString().slice(0, 10), notes: "",
    ingredients: [{ name: "", label_photo: "", bestbefore_photo: "", best_before_date: "", allergens: [] }],
    cooling_logs: [] };
  const [form, setForm] = useState(empty);

  const load = () => api.get("/traceability").then((r) => setItems(r.data)).catch(() => {});
  useEffect(() => { load(); }, []);

  const addIngredient = () => setForm((f) => ({ ...f, ingredients: [...f.ingredients, { name: "", label_photo: "", bestbefore_photo: "", best_before_date: "", allergens: [] }] }));
  const setIng = (i, k, v) => setForm((f) => { const ing = [...f.ingredients]; ing[i] = { ...ing[i], [k]: v }; return { ...f, ingredients: ing }; });
  const toggleAllergen = (i, a) => setForm((f) => { const ing = [...f.ingredients]; const list = ing[i].allergens.includes(a) ? ing[i].allergens.filter((x) => x !== a) : [...ing[i].allergens, a]; ing[i] = { ...ing[i], allergens: list }; return { ...f, ingredients: ing }; });
  const addCooling = () => setForm((f) => ({ ...f, cooling_logs: [...f.cooling_logs, { stage: "", temp: "", time: new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }), note: "" }] }));
  const setCool = (i, k, v) => setForm((f) => { const c = [...f.cooling_logs]; c[i] = { ...c[i], [k]: v }; return { ...f, cooling_logs: c }; });

  const save = async () => {
    if (!form.item_name) return toast.error("Add a dish / prep name");
    try { await api.post("/traceability", form); toast.success("Traceability logged"); setOpen(false); setForm(empty); load(); }
    catch (e) { toast.error(errMsg(e)); }
  };
  const del = async (id) => { await api.delete(`/traceability/${id}`); load(); };

  const allAllergens = (rec) => [...new Set((rec.ingredients || []).flatMap((i) => i.allergens || []))];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><ScanLine className="w-7 h-7 text-primary" /> Product Traceability</h1>
          <p className="text-muted-foreground">Photograph every ingredient label &amp; best-before, log allergens and cooling temps.</p>
        </div>
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild><Button data-testid="add-trace-btn"><Plus className="w-4 h-4 mr-1" /> New log</Button></DialogTrigger>
          <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto">
            <DialogHeader><DialogTitle>New traceability record</DialogTitle></DialogHeader>
            <div className="space-y-4">
              <div className="grid grid-cols-2 gap-3">
                <div><Label>Type</Label>
                  <select data-testid="trace-type" className="w-full h-10 rounded-md border px-3 mt-1 bg-background" value={form.type} onChange={(e) => setForm({ ...form, type: e.target.value })}>
                    <option>Prep</option><option>Recipe</option>
                  </select>
                </div>
                <div><Label>Date</Label><Input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></div>
              </div>
              <div><Label>Dish / Prep name</Label><Input data-testid="trace-name" value={form.item_name} onChange={(e) => setForm({ ...form, item_name: e.target.value })} placeholder="e.g. Marinara Sauce" /></div>

              <div className="space-y-3">
                <div className="flex items-center justify-between"><Label>Ingredients</Label><Button size="sm" variant="outline" onClick={addIngredient} data-testid="add-ingredient-btn"><Plus className="w-4 h-4" /></Button></div>
                {form.ingredients.map((ing, i) => (
                  <Card key={i} className="p-3 space-y-3 bg-secondary/30">
                    <Input placeholder="Ingredient name" value={ing.name} onChange={(e) => setIng(i, "name", e.target.value)} data-testid={`ing-name-${i}`} />
                    <div className="grid grid-cols-2 gap-3">
                      <PhotoUpload label="Label photo" value={ing.label_photo} onChange={(v) => setIng(i, "label_photo", v)} testid={`ing-label-${i}`} />
                      <PhotoUpload label="Best-before photo" value={ing.bestbefore_photo} onChange={(v) => setIng(i, "bestbefore_photo", v)} testid={`ing-bb-${i}`} />
                    </div>
                    <div><Label className="text-xs">Best before date</Label><Input type="date" value={ing.best_before_date} onChange={(e) => setIng(i, "best_before_date", e.target.value)} /></div>
                    <div>
                      <Label className="text-xs">Allergens</Label>
                      <div className="flex flex-wrap gap-1.5 mt-1">
                        {ALLERGENS.map((a) => (
                          <button key={a} type="button" onClick={() => toggleAllergen(i, a)}
                            className={`text-xs px-2 py-1 rounded-full border ${ing.allergens.includes(a) ? "bg-rose-500 text-white border-rose-500" : "bg-background"}`}>{a}</button>
                        ))}
                      </div>
                    </div>
                  </Card>
                ))}
              </div>

              <div className="space-y-2">
                <div className="flex items-center justify-between"><Label className="flex items-center gap-1"><Thermometer className="w-4 h-4" /> Cooling temps</Label><Button size="sm" variant="outline" onClick={addCooling} data-testid="add-cooling-btn"><Plus className="w-4 h-4" /></Button></div>
                <div className="flex gap-2 text-xs bg-blue-50 text-blue-800 rounded-lg p-3 border border-blue-100">
                  <Info className="w-4 h-4 shrink-0 mt-0.5" />
                  <div>
                    <p className="font-semibold">Safe cooling guide (2-hour / 4-hour rule)</p>
                    <p className="mt-0.5">Cool cooked food from <b>60°C → 21°C within 2 hrs</b>, then <b>21°C → 5°C within the next 4 hrs</b>. The <b>danger zone is 5°C–60°C</b> — keep time here to a minimum. Chill / store at <b>5°C or below</b>.</p>
                  </div>
                </div>
                {form.cooling_logs.map((c, i) => {
                  const danger = c.temp !== "" && Number(c.temp) > 5 && Number(c.temp) < 60;
                  return (
                    <div key={i} className="grid grid-cols-3 gap-2">
                      <Input placeholder="Stage e.g. 2hr check" value={c.stage} onChange={(e) => setCool(i, "stage", e.target.value)} />
                      <Input placeholder="°C" value={c.temp} onChange={(e) => setCool(i, "temp", e.target.value)} className={danger ? "border-rose-400 text-rose-600" : ""} />
                      <Input placeholder="Time" value={c.time} onChange={(e) => setCool(i, "time", e.target.value)} />
                      <Input placeholder="Note (e.g. blast chiller, held at 4°C)" value={c.note || ""} onChange={(e) => setCool(i, "note", e.target.value)} className="col-span-3" />
                    </div>
                  );
                })}
              </div>
              <Textarea placeholder="Notes" value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} />
            </div>
            <DialogFooter><Button onClick={save} data-testid="save-trace-btn">Save record</Button></DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        {items.length === 0 && <p className="text-muted-foreground">No records yet. Tap “New log”.</p>}
        {items.map((rec) => (
          <Card key={rec.id} className="p-5 hoverable" data-testid={`trace-card-${rec.id}`}>
            <div className="flex items-start justify-between">
              <div>
                <div className="flex items-center gap-2"><Badge variant="secondary">{rec.type}</Badge><span className="text-xs text-muted-foreground">{rec.date}</span></div>
                <h3 className="font-semibold text-lg mt-1">{rec.item_name}</h3>
              </div>
              <button onClick={() => del(rec.id)} className="text-slate-400 hover:text-rose-500" data-testid={`del-trace-${rec.id}`}><Trash2 className="w-4 h-4" /></button>
            </div>
            {allAllergens(rec).length > 0 && (
              <div className="flex flex-wrap gap-1.5 mt-2">{allAllergens(rec).map((a) => <Badge key={a} className="bg-rose-100 text-rose-700 hover:bg-rose-100">{a}</Badge>)}</div>
            )}
            <div className="flex gap-2 mt-3 flex-wrap">
              {(rec.ingredients || []).flatMap((ing, ii) => [ing.label_photo, ing.bestbefore_photo].filter(Boolean).map((p, pi) => (
                <img key={`${ii}-${pi}`} src={fileUrl(p)} alt="" className="w-16 h-16 object-cover rounded-lg border" />
              )))}
            </div>
            {(rec.cooling_logs || []).length > 0 && (
              <div className="mt-3 flex flex-wrap gap-2">
                {rec.cooling_logs.map((c, i) => {
                  const danger = c.temp !== "" && Number(c.temp) > 5 && Number(c.temp) < 60;
                  return (
                    <div key={i} title={c.note || ""} className={`text-xs rounded-lg px-2 py-1 flex items-center gap-1 ${danger ? "bg-rose-50 text-rose-700" : "bg-blue-50 text-blue-700"}`}>
                      <Thermometer className="w-3 h-3" />{c.stage}: {c.temp}°C @ {c.time}{c.note ? ` · ${c.note}` : ""}
                    </div>
                  );
                })}
              </div>
            )}
            <p className="text-xs text-muted-foreground mt-3">Logged by {rec.created_by}</p>
          </Card>
        ))}
      </div>
    </div>
  );
}
