import React, { useEffect, useMemo, useState } from "react";
import { api, errMsg, fileUrl } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Plus, BookOpen, Trash2, Minus, DollarSign } from "lucide-react";
import { PhotoUpload } from "@/components/PhotoUpload";
import { toast } from "sonner";

const ALLERGENS = ["Gluten", "Dairy", "Egg", "Fish", "Shellfish", "Nuts", "Peanuts", "Soy", "Sesame", "Celery", "Mustard", "Sulphites"];

export default function Recipes() {
  const { isManager } = useAuth();
  const [items, setItems] = useState([]);
  const [inv, setInv] = useState([]);
  const [open, setOpen] = useState(false);
  const [view, setView] = useState(null);
  const [scale, setScale] = useState(1);
  const [sellPrice, setSellPrice] = useState("");
  const empty = { name: "", category: "Main", yield_qty: 1, yield_unit: "serve", shelf_life_days: "", sell_price: "", allergens: [], ingredients: [{ name: "", qty: "", unit: "" }], steps: [""], photo: "" };
  const [form, setForm] = useState(empty);

  const load = () => api.get("/recipes").then((r) => setItems(r.data)).catch(() => {});
  useEffect(() => {
    load();
    if (isManager) api.get("/inventory").then((r) => setInv(r.data)).catch(() => {});
  }, [isManager]);

  const priceMap = useMemo(() => {
    const m = {};
    (inv || []).forEach((it) => { if (it.name) m[it.name.trim().toLowerCase()] = Number(it.cost_per_unit ?? it.price ?? 0); });
    return m;
  }, [inv]);

  const lineCost = (ing) => {
    const p = priceMap[(ing.name || "").trim().toLowerCase()];
    return p != null && !isNaN(p) && p > 0 ? p * Number(ing.qty || 0) : null;
  };
  const recipeCost = (r) => {
    const ings = r.ingredients || [];
    let batch = 0, priced = 0;
    ings.forEach((ing) => { const c = lineCost(ing); if (c != null) { batch += c; priced++; } });
    const yq = Number(r.yield_qty || 1) || 1;
    return { batch, perServe: batch / yq, priced, count: ings.length };
  };
  const gpClass = (gp) => gp >= 65 ? "bg-emerald-100 text-emerald-700" : gp >= 30 ? "bg-amber-100 text-amber-700" : "bg-rose-100 text-rose-700";

  const setIng = (i, k, v) => setForm((f) => { const a = [...f.ingredients]; a[i] = { ...a[i], [k]: v }; return { ...f, ingredients: a }; });
  const setStep = (i, v) => setForm((f) => { const a = [...f.steps]; a[i] = v; return { ...f, steps: a }; });
  const save = async () => {
    if (!form.name) return toast.error("Add a name");
    const payload = { ...form, yield_qty: Number(form.yield_qty), sell_price: Number(form.sell_price) || 0, ingredients: form.ingredients.filter((i) => i.name), steps: form.steps.filter(Boolean) };
    try { await api.post("/recipes", payload); toast.success("Recipe saved"); setOpen(false); setForm(empty); load(); } catch (e) { toast.error(errMsg(e)); }
  };
  const del = async (id) => { await api.delete(`/recipes/${id}`); load(); };
  const openView = (r) => { setView(r); setScale(1); setSellPrice(r.sell_price ? String(r.sell_price) : ""); };
  const saveSell = async () => {
    const payload = { ...view, sell_price: Number(sellPrice) || 0 };
    try {
      await api.put(`/recipes/${view.id}`, payload);
      setView(payload); setItems((xs) => xs.map((x) => x.id === view.id ? payload : x));
      toast.success("Sell price saved");
    } catch (e) { toast.error(errMsg(e)); }
  };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><BookOpen className="w-7 h-7 text-primary" /> Recipes</h1>
          <p className="text-muted-foreground">Method cards with batch scaling.</p>
        </div>
        {isManager && (
          <Dialog open={open} onOpenChange={setOpen}>
            <DialogTrigger asChild><Button data-testid="add-recipe-btn"><Plus className="w-4 h-4 mr-1" /> New recipe</Button></DialogTrigger>
            <DialogContent className="max-w-xl max-h-[90vh] overflow-y-auto">
              <DialogHeader><DialogTitle>New recipe</DialogTitle></DialogHeader>
              <div className="space-y-3">
                <div><Label>Name</Label><Input data-testid="recipe-name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
                <div className="grid grid-cols-3 gap-3">
                  <div><Label>Category</Label><Input value={form.category} onChange={(e) => setForm({ ...form, category: e.target.value })} /></div>
                  <div><Label>Yield qty</Label><Input type="number" value={form.yield_qty} onChange={(e) => setForm({ ...form, yield_qty: e.target.value })} /></div>
                  <div><Label>Unit</Label><Input value={form.yield_unit} onChange={(e) => setForm({ ...form, yield_unit: e.target.value })} /></div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Shelf life (days)</Label><Input type="number" data-testid="recipe-shelf" value={form.shelf_life_days} onChange={(e) => setForm({ ...form, shelf_life_days: e.target.value })} placeholder="e.g. 3" /></div>
                  <div><Label>Sell price ($/serve)</Label><Input type="number" data-testid="recipe-sell-price" value={form.sell_price} onChange={(e) => setForm({ ...form, sell_price: e.target.value })} placeholder="e.g. 24" /></div>
                </div>
                <div>
                  <Label>Allergens</Label>
                  <div className="flex flex-wrap gap-1.5 mt-1">
                    {ALLERGENS.map((a) => (
                      <button key={a} type="button" onClick={() => setForm((f) => ({ ...f, allergens: f.allergens.includes(a) ? f.allergens.filter((x) => x !== a) : [...f.allergens, a] }))}
                        className={`text-xs px-2 py-1 rounded-full border ${form.allergens.includes(a) ? "bg-rose-500 text-white border-rose-500" : "bg-background"}`}>{a}</button>
                    ))}
                  </div>
                </div>
                <PhotoUpload label="Reference / plating photo (stock standard)" value={form.photo} onChange={(v) => setForm({ ...form, photo: v })} testid="recipe-photo" />
                <div>
                  <div className="flex items-center justify-between"><Label>Ingredients</Label><Button size="sm" variant="outline" onClick={() => setForm((f) => ({ ...f, ingredients: [...f.ingredients, { name: "", qty: "", unit: "" }] }))}><Plus className="w-4 h-4" /></Button></div>
                  {form.ingredients.map((ing, i) => (
                    <div key={i} className="grid grid-cols-6 gap-2 mt-2">
                      <Input className="col-span-3" placeholder="Name" value={ing.name} onChange={(e) => setIng(i, "name", e.target.value)} />
                      <Input className="col-span-1" placeholder="Qty" value={ing.qty} onChange={(e) => setIng(i, "qty", e.target.value)} />
                      <Input className="col-span-2" placeholder="Unit" value={ing.unit} onChange={(e) => setIng(i, "unit", e.target.value)} />
                    </div>
                  ))}
                </div>
                <div>
                  <div className="flex items-center justify-between"><Label>Steps</Label><Button size="sm" variant="outline" onClick={() => setForm((f) => ({ ...f, steps: [...f.steps, ""] }))}><Plus className="w-4 h-4" /></Button></div>
                  {form.steps.map((s, i) => <Textarea key={i} className="mt-2" rows={2} placeholder={`Step ${i + 1}`} value={s} onChange={(e) => setStep(i, e.target.value)} />)}
                </div>
              </div>
              <DialogFooter><Button onClick={save} data-testid="save-recipe-btn">Save</Button></DialogFooter>
            </DialogContent>
          </Dialog>
        )}
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {items.map((r) => (
          <Card key={r.id} className="p-5 hoverable cursor-pointer" onClick={() => openView(r)} data-testid={`recipe-${r.id}`}>
            {r.photo && <img src={fileUrl(r.photo)} alt={r.name} className="w-full h-32 object-cover rounded-lg border mb-3" />}
            <div className="flex items-start justify-between">
              <div><Badge variant="secondary">{r.category}</Badge><h3 className="font-semibold text-lg mt-1.5">{r.name}</h3></div>
              {isManager && <button onClick={(e) => { e.stopPropagation(); del(r.id); }} className="text-slate-400 hover:text-rose-500"><Trash2 className="w-4 h-4" /></button>}
            </div>
            <p className="text-sm text-muted-foreground mt-1">Yields {r.yield_qty} {r.yield_unit} · {(r.ingredients || []).length} ingredients</p>
            {isManager && (() => {
              const c = recipeCost(r);
              if (c.priced === 0) return null;
              const sp = Number(r.sell_price || 0);
              const gp = sp > 0 ? ((r.yield_qty * sp - c.batch) / (r.yield_qty * sp)) * 100 : null;
              return (
                <div className="flex flex-wrap items-center gap-1.5 mt-2" data-testid={`recipe-cost-${r.id}`}>
                  <Badge className="bg-slate-100 text-slate-700 hover:bg-slate-100 font-mono text-[11px]">${c.perServe.toFixed(2)}/serve cost</Badge>
                  {gp != null && <Badge className={`${gpClass(gp)} hover:bg-transparent font-mono text-[11px]`}>GP {gp.toFixed(0)}%</Badge>}
                </div>
              );
            })()}
            {(r.allergens || []).length > 0 && <div className="flex flex-wrap gap-1 mt-2">{r.allergens.map((a) => <Badge key={a} className="bg-rose-100 text-rose-700 hover:bg-rose-100 text-[10px]">{a}</Badge>)}</div>}
          </Card>
        ))}
      </div>

      <Dialog open={!!view} onOpenChange={(v) => !v && setView(null)}>
        <DialogContent className="max-w-lg max-h-[90vh] overflow-y-auto">
          {view && (<>
            <DialogHeader><DialogTitle>{view.name}</DialogTitle></DialogHeader>
            {view.photo && <img src={fileUrl(view.photo)} alt={view.name} className="w-full h-48 object-cover rounded-xl border mb-3" />}
            <div className="flex items-center gap-2 mb-3">
              <span className="text-sm text-muted-foreground">Batch:</span>
              {[0.5, 1, 2, 5].map((m) => (
                <button key={m} onClick={() => setScale(m)} className={`px-3 py-1 rounded-full text-sm border ${scale === m ? "brand-gradient text-white" : "bg-background"}`} data-testid={`scale-${m}`}>×{m}</button>
              ))}
              <span className="ml-auto text-sm font-mono">{(view.yield_qty * scale).toFixed(2).replace(/\.00$/, "")} {view.yield_unit}</span>
            </div>
            <h4 className="font-semibold mb-1">Ingredients</h4>
            <div className="divide-y mb-4">
              {(view.ingredients || []).map((ing, i) => {
                const c = lineCost(ing);
                return (
                  <div key={i} className="flex justify-between items-center py-1.5 text-sm">
                    <span>{ing.name}</span>
                    <span className="flex items-center gap-3">
                      <span className="font-mono">{(Number(ing.qty) * scale).toFixed(2).replace(/\.00$/, "")} {ing.unit}</span>
                      {isManager && <span className={`font-mono text-xs w-16 text-right ${c == null ? "text-slate-300" : "text-slate-500"}`}>{c == null ? "—" : `$${(c * scale).toFixed(2)}`}</span>}
                    </span>
                  </div>
                );
              })}
            </div>
            {isManager && (() => {
              const c = recipeCost(view);
              const sp = Number(sellPrice) || 0;
              const perServeSell = sp;
              const gp = sp > 0 ? ((sp - c.perServe) / sp) * 100 : null;
              return (
                <div className="rounded-xl border bg-slate-50 p-4 mb-4" data-testid="recipe-cost-panel">
                  <div className="flex items-center gap-2 mb-3 font-semibold text-sm"><DollarSign className="w-4 h-4 text-primary" /> Plate costing</div>
                  <div className="grid grid-cols-2 gap-x-4 gap-y-1.5 text-sm">
                    <span className="text-muted-foreground">Batch cost ({view.yield_qty} {view.yield_unit})</span>
                    <span className="font-mono text-right">${c.batch.toFixed(2)}</span>
                    <span className="text-muted-foreground">Cost per serve</span>
                    <span className="font-mono text-right font-semibold">${c.perServe.toFixed(2)}</span>
                  </div>
                  {c.priced < c.count && <p className="text-[11px] text-amber-600 mt-2">{c.priced}/{c.count} ingredients priced — add matching names to Inventory for an exact cost.</p>}
                  <div className="flex items-end gap-3 mt-3 pt-3 border-t">
                    <div className="flex-1">
                      <Label className="text-xs">Sell price ($/serve)</Label>
                      <Input type="number" value={sellPrice} onChange={(e) => setSellPrice(e.target.value)} placeholder="e.g. 24" data-testid="view-sell-price" className="mt-1 h-9" />
                    </div>
                    <Button size="sm" onClick={saveSell} data-testid="save-sell-price" className="h-9">Save</Button>
                  </div>
                  {gp != null && (
                    <div className="flex items-center justify-between mt-3 text-sm">
                      <span className="text-muted-foreground">Gross profit</span>
                      <span className="flex items-center gap-2">
                        <span className="font-mono">${(perServeSell - c.perServe).toFixed(2)}/serve</span>
                        <Badge className={`${gpClass(gp)} hover:bg-transparent font-mono`} data-testid="view-gp">GP {gp.toFixed(0)}%</Badge>
                      </span>
                    </div>
                  )}
                </div>
              );
            })()}
            <h4 className="font-semibold mb-1">Method</h4>
            <ol className="space-y-2">
              {(view.steps || []).map((s, i) => (
                <li key={i} className="flex gap-3 text-sm"><span className="w-6 h-6 rounded-full brand-gradient text-white grid place-items-center text-xs shrink-0">{i + 1}</span><span>{s}</span></li>
              ))}
            </ol>
          </>)}
        </DialogContent>
      </Dialog>
    </div>
  );
}
