import React, { useEffect, useState } from "react";
import { api, errMsg } from "@/lib/api";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Tabs, TabsList, TabsTrigger, TabsContent } from "@/components/ui/tabs";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Plus, Phone, Clock, Truck, Trash2, Send, CheckCircle2, Timer } from "lucide-react";
import { toast } from "sonner";

const DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
const DAY_INDEX = { Sun: 0, Mon: 1, Tue: 2, Wed: 3, Thu: 4, Fri: 5, Sat: 6 };

function nextCutoff(orderDays, cutoffTime) {
  if (!orderDays || orderDays.length === 0 || !cutoffTime) return null;
  const [h, m] = cutoffTime.split(":").map(Number);
  const now = new Date();
  for (let off = 0; off <= 7; off++) {
    const d = new Date(now);
    d.setDate(now.getDate() + off);
    const abbr = Object.keys(DAY_INDEX).find((k) => DAY_INDEX[k] === d.getDay());
    if (orderDays.includes(abbr)) {
      d.setHours(h, m, 0, 0);
      if (d > now) return d;
    }
  }
  return null;
}

function CutoffTimer({ supplier }) {
  const [now, setNow] = useState(Date.now());
  useEffect(() => { const id = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(id); }, []);
  const target = nextCutoff(supplier.order_days, supplier.cutoff_time);
  if (!target) return null;
  const diff = Math.max(0, target.getTime() - now);
  const d = Math.floor(diff / 86400000);
  const h = Math.floor((diff % 86400000) / 3600000);
  const mm = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  const urgent = diff < 3 * 3600000;
  const label = d > 0 ? `${d}d ${h}h ${mm}m` : `${String(h).padStart(2, "0")}:${String(mm).padStart(2, "0")}:${String(s).padStart(2, "0")}`;
  return (
    <div className={`mt-3 rounded-xl p-3 flex items-center gap-2 ${urgent ? "bg-rose-50 text-rose-700" : "bg-orange-50 text-orange-700"}`} data-testid={`cutoff-${supplier.id}`}>
      <Timer className="w-4 h-4 shrink-0" />
      <div className="text-xs">
        <p className="font-semibold">Next order cut-off</p>
        <p>{target.toLocaleDateString(undefined, { weekday: "short" })} {supplier.cutoff_time} · <span className="font-mono font-bold">{label}</span> left</p>
      </div>
    </div>
  );
}

export default function Suppliers() {
  const [suppliers, setSuppliers] = useState([]);
  const [orders, setOrders] = useState([]);
  const [open, setOpen] = useState(false);
  const empty = { name: "", phone: "", email: "", order_days: [], delivery_days: [], cutoff_time: "14:00", notes: "" };
  const [form, setForm] = useState(empty);

  const load = () => {
    api.get("/suppliers").then((r) => setSuppliers(r.data)).catch(() => {});
    api.get("/orders").then((r) => setOrders(r.data)).catch(() => {});
  };
  useEffect(() => { load(); }, []);

  const toggleDay = (field, d) => setForm((f) => ({ ...f, [field]: f[field].includes(d) ? f[field].filter((x) => x !== d) : [...f[field], d] }));
  const save = async () => {
    if (!form.name) return toast.error("Add supplier name");
    try { await api.post("/suppliers", form); toast.success("Supplier added"); setOpen(false); setForm(empty); load(); }
    catch (e) { toast.error(errMsg(e)); }
  };
  const delSup = async (id) => { await api.delete(`/suppliers/${id}`); load(); };
  const markOrdered = async (o) => { await api.put(`/orders/${o.id}`, { status: "ordered" }); toast.success("Marked as ordered"); load(); };
  const supName = (id) => suppliers.find((s) => s.id === id)?.name || "";

  const drafts = orders.filter((o) => o.status === "draft");
  const placed = orders.filter((o) => o.status !== "draft");

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><Truck className="w-7 h-7 text-primary" /> Suppliers &amp; Orders</h1>
          <p className="text-muted-foreground">Order days, cut-offs, delivery days and auto-generated orders.</p>
        </div>
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild><Button data-testid="add-supplier-btn"><Plus className="w-4 h-4 mr-1" /> Add supplier</Button></DialogTrigger>
          <DialogContent className="max-h-[90vh] overflow-y-auto">
            <DialogHeader><DialogTitle>Add supplier</DialogTitle></DialogHeader>
            <div className="space-y-3">
              <div><Label>Name</Label><Input data-testid="sup-name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
              <div className="grid grid-cols-2 gap-3">
                <div><Label>Phone</Label><Input data-testid="sup-phone" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} /></div>
                <div><Label>Cut-off time</Label><Input type="time" value={form.cutoff_time} onChange={(e) => setForm({ ...form, cutoff_time: e.target.value })} /></div>
              </div>
              <div><Label>Email</Label><Input value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></div>
              <div><Label>Order days</Label><div className="flex flex-wrap gap-1.5 mt-1">{DAYS.map((d) => <button key={d} type="button" onClick={() => toggleDay("order_days", d)} className={`text-xs px-2.5 py-1 rounded-full border ${form.order_days.includes(d) ? "brand-gradient text-white" : "bg-background"}`}>{d}</button>)}</div></div>
              <div><Label>Delivery days</Label><div className="flex flex-wrap gap-1.5 mt-1">{DAYS.map((d) => <button key={d} type="button" onClick={() => toggleDay("delivery_days", d)} className={`text-xs px-2.5 py-1 rounded-full border ${form.delivery_days.includes(d) ? "bg-emerald-500 text-white border-emerald-500" : "bg-background"}`}>{d}</button>)}</div></div>
              <div><Label>Notes</Label><Input value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></div>
            </div>
            <DialogFooter><Button onClick={save} data-testid="save-supplier-btn">Save</Button></DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      <Tabs defaultValue="orders">
        <TabsList>
          <TabsTrigger value="orders" data-testid="tab-orders">Orders {drafts.length > 0 && <Badge className="ml-1.5 brand-gradient text-white">{drafts.length}</Badge>}</TabsTrigger>
          <TabsTrigger value="suppliers" data-testid="tab-suppliers">Suppliers</TabsTrigger>
        </TabsList>

        <TabsContent value="orders" className="space-y-4 mt-4">
          <h3 className="font-semibold text-lg">Draft orders (auto-generated)</h3>
          {drafts.length === 0 && <p className="text-muted-foreground text-sm">No draft orders — stock is above par. 🎉</p>}
          {drafts.map((o) => (
            <Card key={o.id} className="p-5" data-testid={`order-${o.id}`}>
              <div className="flex items-center justify-between mb-3">
                <div><h4 className="font-semibold">{o.supplier_name || supName(o.supplier_id)}</h4><Badge variant="secondary">Draft</Badge></div>
                <Button size="sm" onClick={() => markOrdered(o)} data-testid={`place-order-${o.id}`}><Send className="w-4 h-4 mr-1" /> Mark ordered</Button>
              </div>
              <div className="divide-y">
                {(o.items || []).map((it) => (
                  <div key={it.inventory_id} className="flex items-center justify-between py-2 text-sm">
                    <span>{it.name} <span className="text-muted-foreground">({it.current_qty}/{it.par_level} {it.unit})</span></span>
                    <span className="font-mono font-semibold text-primary">order {it.order_qty} {it.unit}</span>
                  </div>
                ))}
              </div>
            </Card>
          ))}
          {placed.length > 0 && <h3 className="font-semibold text-lg pt-2">Placed orders</h3>}
          {placed.map((o) => (
            <Card key={o.id} className="p-4 opacity-80" data-testid={`placed-${o.id}`}>
              <div className="flex items-center justify-between">
                <span className="font-medium">{o.supplier_name || supName(o.supplier_id)}</span>
                <Badge className="bg-emerald-100 text-emerald-700 hover:bg-emerald-100"><CheckCircle2 className="w-3 h-3 mr-1" /> Ordered</Badge>
              </div>
              <p className="text-xs text-muted-foreground mt-1">{(o.items || []).map((i) => `${i.name} ×${i.order_qty}`).join(", ")}</p>
            </Card>
          ))}
        </TabsContent>

        <TabsContent value="suppliers" className="grid gap-4 md:grid-cols-2 mt-4">
          {suppliers.map((s) => (
            <Card key={s.id} className="p-5 hoverable" data-testid={`supplier-${s.id}`}>
              <div className="flex items-start justify-between">
                <h3 className="font-semibold text-lg">{s.name}</h3>
                <button onClick={() => delSup(s.id)} className="text-slate-400 hover:text-rose-500"><Trash2 className="w-4 h-4" /></button>
              </div>
              <div className="mt-2 space-y-1.5 text-sm">
                <p className="flex items-center gap-2 text-muted-foreground"><Phone className="w-4 h-4" /> {s.phone || "—"}</p>
                <p className="flex items-center gap-2 text-muted-foreground"><Clock className="w-4 h-4" /> Cut-off {s.cutoff_time}</p>
              </div>
              <CutoffTimer supplier={s} />
              <div className="mt-3 space-y-2">
                <div><span className="text-xs text-muted-foreground">Order days</span><div className="flex gap-1 mt-1">{(s.order_days || []).map((d) => <Badge key={d} variant="secondary" className="text-[10px]">{d}</Badge>)}</div></div>
                <div><span className="text-xs text-muted-foreground">Delivery days</span><div className="flex gap-1 mt-1">{(s.delivery_days || []).map((d) => <Badge key={d} className="bg-emerald-100 text-emerald-700 hover:bg-emerald-100 text-[10px]">{d}</Badge>)}</div></div>
              </div>
              {s.notes && <p className="text-xs text-muted-foreground mt-3 italic">{s.notes}</p>}
            </Card>
          ))}
        </TabsContent>
      </Tabs>
    </div>
  );
}
