import React, { useEffect, useState } from "react";
import { api, errMsg } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { Clock, Play, Square } from "lucide-react";
import { toast } from "sonner";

export default function Timesheets() {
  const { user, isManager } = useAuth();
  const [rows, setRows] = useState([]);
  const [active, setActive] = useState(null);
  const [elapsed, setElapsed] = useState("");

  const load = () => {
    api.get("/timesheets").then((r) => setRows(r.data)).catch(() => {});
    api.get("/timesheets/active").then((r) => setActive(r.data)).catch(() => {});
  };
  useEffect(() => { load(); }, []);

  useEffect(() => {
    if (!active) { setElapsed(""); return; }
    const tick = () => {
      const secs = Math.floor((Date.now() - new Date(active.clock_in).getTime()) / 1000);
      const h = String(Math.floor(secs / 3600)).padStart(2, "0");
      const m = String(Math.floor((secs % 3600) / 60)).padStart(2, "0");
      const s = String(secs % 60).padStart(2, "0");
      setElapsed(`${h}:${m}:${s}`);
    };
    tick(); const id = setInterval(tick, 1000); return () => clearInterval(id);
  }, [active]);

  const clockIn = async () => { try { await api.post("/timesheets/clock-in"); toast.success("Clocked in — have a great shift!"); load(); } catch (e) { toast.error(errMsg(e)); } };
  const clockOut = async () => { try { const { data } = await api.post("/timesheets/clock-out"); toast.success(`Clocked out — ${data.hours}h worked`); load(); } catch (e) { toast.error(errMsg(e)); } };

  const fmt = (iso) => iso ? new Date(iso).toLocaleString(undefined, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }) : "—";

  return (
    <div className="space-y-6">
      <div>
        <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><Clock className="w-7 h-7 text-primary" /> {isManager ? "Timesheets" : "My Timesheet"}</h1>
        <p className="text-muted-foreground">Clock in and out — hours are calculated automatically.</p>
      </div>

      <Card className="p-6 flex flex-col sm:flex-row items-center justify-between gap-4">
        <div>
          <p className="text-sm text-muted-foreground">{active ? "On shift since" : "You are off the clock"}</p>
          <p className="text-4xl font-bold font-mono mt-1">{active ? elapsed : "--:--:--"}</p>
          {active && <p className="text-xs text-muted-foreground mt-1">Started {fmt(active.clock_in)}</p>}
        </div>
        {active ? (
          <Button size="lg" variant="destructive" onClick={clockOut} data-testid="clock-out-btn" className="h-14 px-8 text-lg"><Square className="w-5 h-5 mr-2" /> Clock out</Button>
        ) : (
          <Button size="lg" onClick={clockIn} data-testid="clock-in-btn" className="h-14 px-8 text-lg"><Play className="w-5 h-5 mr-2" /> Clock in</Button>
        )}
      </Card>

      <Card className="p-0 overflow-hidden">
        <Table>
          <TableHeader>
            <TableRow>
              {isManager && <TableHead>Staff</TableHead>}
              <TableHead>Clock in</TableHead>
              <TableHead>Clock out</TableHead>
              <TableHead className="text-right">Hours</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {rows.map((r) => (
              <TableRow key={r.id} data-testid={`ts-row-${r.id}`}>
                {isManager && <TableCell className="font-medium">{r.staff_name}</TableCell>}
                <TableCell>{fmt(r.clock_in)}</TableCell>
                <TableCell>{r.clock_out ? fmt(r.clock_out) : <Badge className="bg-emerald-100 text-emerald-700 hover:bg-emerald-100">On shift</Badge>}</TableCell>
                <TableCell className="text-right font-mono font-semibold">{r.clock_out ? `${r.hours}h` : "—"}</TableCell>
              </TableRow>
            ))}
            {rows.length === 0 && <TableRow><TableCell colSpan={isManager ? 4 : 3} className="text-center text-muted-foreground py-8">No shifts recorded yet.</TableCell></TableRow>}
          </TableBody>
        </Table>
      </Card>
    </div>
  );
}
