import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { api, fileUrl, errMsg } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";
import { ChefHat, Delete, ArrowLeft } from "lucide-react";
import { toast } from "sonner";

export default function Login() {
  const { login, user } = useAuth();
  const navigate = useNavigate();
  const [tiles, setTiles] = useState([{ id: 1, staff_id: "1", name: "Test Staff", photo_url: "" }]);
  const [selected, setSelected] = useState(null);
  const [pin, setPin] = useState("");
  const [busy, setBusy] = useState(false);

  useEffect(() => { if (user) navigate("/"); }, [user, navigate]);

  const submit = async (fullPin) => {
    setBusy(true);
    try {
      await login(selected.staff_id, fullPin);
      toast.success(`Welcome back, ${selected?.name?.split(" ")[0]}`);
      navigate("/");
    } catch (e) {
      toast.error(errMsg(e, "Wrong PIN"));
      setPin("");
    } finally {
      setBusy(false);
    }
  };

  const press = (d) => {
    if (pin.length >= 4) return;
    const next = pin + d;
    setPin(next);
    if (next.length === 4) submit(next);
  };

  return (
    <div className="min-h-screen flex flex-col bg-gradient-to-br from-background to-muted">
      <div className="flex items-center gap-2.5 px-6 py-5">
        <div className="w-9 h-9 rounded-xl brand-gradient grid place-items-center">
          <ChefHat className="w-5 h-5 text-white" />
        </div>
        <span className="font-bold text-lg tracking-tight">Culinary Pulse Kitchen</span>
      </div>

      <div className="flex-1 flex items-center justify-center px-4 pb-12">
        {!selected ? (
          <div className="w-full max-w-3xl">
            <h1 className="text-3xl sm:text-4xl font-bold text-center mb-2">Who is signing in?</h1>
            <p className="text-center text-muted-foreground mt-2 mb-8">Select your profile tile to continue</p>
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-4">
              {(tiles || []).map((t) => (
                <button key={t.id} data-testid={`staff-tile-${t.staff_id}`} onClick={() => setSelected(t)}
                  className="hoverable bg-card rounded-2xl border p-4 flex flex-col items-center justify-center transition-all duration-200">
                  <img src={t.photo_url?.startsWith("http") ? t.photo_url : "/avatar-placeholder.png"} 
                    className="w-20 h-20 rounded-full object-cover mb-3" 
                    onError={(e) => { e.target.style.visibility = "hidden"; }} />
                  <p className="font-semibold text-sm leading-tight">{t.name}</p>
                  <p className="text-xs text-muted-foreground mt-0.5">Tap to sign in</p>
                </button>
              ))}
            </div>
          </div>
        ) : (
          <div className="w-full max-w-xs">
            <button data-testid="back-to-tiles" onClick={() => { setSelected(null); setPin(""); }}
              className="flex items-center gap-2 text-sm text-muted-foreground hover:text-foreground mb-6 transition-colors">
              <ArrowLeft className="w-4 h-4" /> Back
            </button>
            <div className="bg-card border rounded-3xl p-6 shadow-sm flex flex-col items-center">
              <img src={selected.photo_url?.startsWith("http") ? selected.photo_url : "/avatar-placeholder.png"} 
                className="w-16 h-16 rounded-full object-cover mb-3" />
              <h2 className="font-bold text-lg">{selected.name}</h2>
              <p className="text-xs text-muted-foreground mb-6">Enter your 4-digit PIN</p>
              
              <div className="flex gap-3 mb-8">
                {[...Array(4)].map((_, i) => (
                  <div key={i} className={`w-3 h-3 rounded-full border-2 transition-all ${pin.length > i ? "bg-primary border-primary scale-110" : "border-muted-foreground/30"}`} />
                ))}
              </div>

              <div className="grid grid-cols-3 gap-4 w-full max-w-[240px]">
                {[1, 2, 3, 4, 5, 6, 7, 8, 9].map((d) => (
                  <button key={d} onClick={() => press(d.toString())} disabled={busy}
                    className="h-14 rounded-2xl border bg-background font-semibold text-lg hover:bg-muted active:scale-95 transition-all">
                    {d}
                  </button>
                ))}
                <button onClick={() => setPin("")} disabled={busy} className="text-xs font-semibold text-muted-foreground hover:text-foreground">Clear</button>
                <button onClick={() => press("0")} disabled={busy} className="h-14 rounded-2xl border bg-background font-semibold text-lg hover:bg-muted active:scale-95 transition-all">0</button>
                <button onClick={() => setPin(pin.slice(0, -1))} disabled={busy} className="grid place-items-center text-muted-foreground hover:text-foreground">
                  <Delete className="w-5 h-5" />
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
