import React, { useEffect, useState } from "react";
import { api, fileUrl, errMsg } from "@/lib/api";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { PhotoUpload } from "@/components/PhotoUpload";
import { Plus, PackageCheck, Thermometer, FileText, Trash2, Info } from "lucide-react";
import { toast } from "sonner";

export default function Deliveries() {
  const [items, setItems] = useState([]);
  const [suppliers, setSuppliers] = useState([]);
  const [open, setOpen] = useState(false);
  const empty = { supplier_id: "", date: new Date().toISOString().slice(0, 10), temp: "", temp_photo: "", invoice_photo: "", notes: "" };
  const [form, setForm] = useState(empty);

  const load = () => {
    api.get("/deliveries").then((r) => setItems(r.data)).catch(() => {});
    api.get("/suppliers").then((r) => setSuppliers(r.data)).catch(() => {});
  };
  useEffect(() => { load(); }, []);
  const supName = (id) => suppliers.find((s) => s.id === id)?.name || "—";

  const save = async () => {
    if (!form.supplier_id) return toast.error("Choose a supplier");
    if (!form.temp_photo) return toast.error("Delivery temp photo required");
    const payload = { ...form, supplier_name: supName(form.supplier_id) };
    try { await api.post("/deliveries", payload); toast.success("Delivery recorded"); setOpen(false); setForm(empty); load(); }
    catch (e) { toast.error(errMsg(e)); }
  };
  const del = async (id) => { await api.delete(`/deliveries/${id}`); load(); };

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><PackageCheck className="w-7 h-7 text-primary" /> Deliveries</h1>
          <p className="text-muted-foreground">Record probe temperature photo &amp; upload the invoice on delivery day.</p>
        </div>
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger asChild><Button data-testid="add-delivery-btn"><Plus className="w-4 h-4 mr-1" /> Record delivery</Button></DialogTrigger>
          <DialogContent className="max-h-[90vh] overflow-y-auto">
            <DialogHeader><DialogTitle>Record delivery</DialogTitle></DialogHeader>
            <div className="space-y-3">
              <div className="grid grid-cols-2 gap-3">
                <div><Label>Supplier</Label>
                  <select data-testid="del-supplier" className="w-full h-10 rounded-md border px-3 mt-1 bg-background" value={form.supplier_id} onChange={(e) => setForm({ ...form, supplier_id: e.target.value })}>
                    <option value="">— choose —</option>
                    {suppliers.map((s) => <option key={s.id} value={s.id}>{s.name}</option>)}
                  </select>
                </div>
                <div><Label>Date</Label><Input type="date" value={form.date} onChange={(e) => setForm({ ...form, date: e.target.value })} /></div>
              </div>
              <div className="flex gap-2 text-xs bg-blue-50 text-blue-800 rounded-lg p-3 border border-blue-100">
                <Info className="w-4 h-4 shrink-0 mt-0.5" />
                <div>
                  <p className="font-semibold">Safe delivery temperatures</p>
                  <p className="mt-0.5">Chilled goods should arrive at <b>5°C or below</b>. Frozen goods at <b>−18°C or below</b>. Reject and note anything warmer.</p>
                </div>
              </div>
              <div><Label>Probe temperature (°C)</Label><Input data-testid="del-temp" value={form.temp} onChange={(e) => setForm({ ...form, temp: e.target.value })} placeholder="e.g. 3.5" /></div>
              <PhotoUpload label="Delivery temp photo" value={form.temp_photo} onChange={(v) => setForm({ ...form, temp_photo: v })} testid="del-temp-photo" />
              <PhotoUpload label="Invoice upload" value={form.invoice_photo} onChange={(v) => setForm({ ...form, invoice_photo: v })} testid="del-invoice-photo" />
              <div><Label>Notes</Label><Input value={form.notes} onChange={(e) => setForm({ ...form, notes: e.target.value })} /></div>
            </div>
            <DialogFooter><Button onClick={save} data-testid="save-delivery-btn">Save</Button></DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      <div className="grid gap-4 md:grid-cols-2">
        {items.length === 0 && <p className="text-muted-foreground">No deliveries recorded yet.</p>}
        {items.map((d) => {
          const tempOk = d.temp === "" || Number(d.temp) <= 5;
          return (
            <Card key={d.id} className="p-5 hoverable" data-testid={`delivery-${d.id}`}>
              <div className="flex items-start justify-between">
                <div><h3 className="font-semibold text-lg">{d.supplier_name || supName(d.supplier_id)}</h3><p className="text-xs text-muted-foreground">{d.date}</p></div>
                <button onClick={() => del(d.id)} className="text-slate-400 hover:text-rose-500"><Trash2 className="w-4 h-4" /></button>
              </div>
              <Badge className={`mt-2 ${tempOk ? "bg-emerald-100 text-emerald-700" : "bg-rose-100 text-rose-700"} hover:bg-transparent`}>
                <Thermometer className="w-3 h-3 mr-1" /> {d.temp || "—"}°C {tempOk ? "OK" : "HIGH"}
              </Badge>
              <div className="flex gap-3 mt-3">
                {d.temp_photo && <div className="flex-1"><p className="text-xs text-muted-foreground mb-1">Temp</p><img src={fileUrl(d.temp_photo)} alt="temp" className="w-full h-28 object-cover rounded-lg border" /></div>}
                {d.invoice_photo && <div className="flex-1"><p className="text-xs text-muted-foreground mb-1 flex items-center gap-1"><FileText className="w-3 h-3" />Invoice</p><img src={fileUrl(d.invoice_photo)} alt="invoice" className="w-full h-28 object-cover rounded-lg border" /></div>}
              </div>
              {d.notes && <p className="text-xs text-muted-foreground mt-2 italic">{d.notes}</p>}
            </Card>
          );
        })}
      </div>
    </div>
  );
}
