import React, { useEffect, useState } from "react";
import { api, fileUrl, errMsg } from "@/lib/api";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Badge } from "@/components/ui/badge";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { PhotoUpload } from "@/components/PhotoUpload";
import { Plus, Users, Phone, Trash2, Pencil } from "lucide-react";
import { toast } from "sonner";

export default function Staff() {
  const [staff, setStaff] = useState([]);
  const [open, setOpen] = useState(false);
  const empty = { staff_id: "", name: "", role: "staff", pin: "", phone: "", email: "", photo_url: "" };
  const [form, setForm] = useState(empty);
  const [editId, setEditId] = useState(null);

  const load = () => api.get("/staff").then((r) => setStaff(r.data)).catch(() => {});
  useEffect(() => { load(); }, []);

  const save = async () => {
    if (!form.name || !form.staff_id) return toast.error("Name and ID number required");
    if (!editId && !form.pin) return toast.error("Set a PIN");
    try {
      if (editId) { const payload = { ...form }; if (!payload.pin) delete payload.pin; await api.put(`/staff/${editId}`, payload); }
      else await api.post("/staff", form);
      toast.success("Saved"); setOpen(false); setForm(empty); setEditId(null); load();
    } catch (e) { toast.error(errMsg(e)); }
  };
  const edit = (s) => { setForm({ ...empty, ...s, pin: "" }); setEditId(s.id); setOpen(true); };
  const del = async (id) => { await api.delete(`/staff/${id}`); toast.success("Staff deactivated"); load(); };

  const roleColor = (r) => r === "owner" ? "bg-orange-100 text-orange-700" : r === "manager" ? "bg-blue-100 text-blue-700" : "bg-slate-100 text-slate-700";

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><Users className="w-7 h-7 text-primary" /> Staff</h1>
          <p className="text-muted-foreground">Manage logins, PINs and access. Staff = roster + timesheets only.</p>
        </div>
        <Dialog open={open} onOpenChange={(v) => { setOpen(v); if (!v) { setForm(empty); setEditId(null); } }}>
          <DialogTrigger asChild><Button data-testid="add-staff-btn"><Plus className="w-4 h-4 mr-1" /> Add staff</Button></DialogTrigger>
          <DialogContent className="max-h-[90vh] overflow-y-auto">
            <DialogHeader><DialogTitle>{editId ? "Edit staff" : "Add staff member"}</DialogTitle></DialogHeader>
            <div className="space-y-3">
              <PhotoUpload label="Photo (for login tile)" value={form.photo_url && !form.photo_url.startsWith("http") ? form.photo_url : ""} onChange={(v) => setForm({ ...form, photo_url: v })} testid="staff-photo" />
              <div className="grid grid-cols-2 gap-3">
                <div><Label>Name</Label><Input data-testid="staff-name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
                <div><Label>ID number</Label><Input data-testid="staff-id" value={form.staff_id} onChange={(e) => setForm({ ...form, staff_id: e.target.value })} disabled={!!editId} /></div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div><Label>Role</Label>
                  <select data-testid="staff-role" className="w-full h-10 rounded-md border px-3 mt-1 bg-background" value={form.role} onChange={(e) => setForm({ ...form, role: e.target.value })}>
                    <option value="staff">Staff (roster + timesheets)</option>
                    <option value="manager">Manager (full access)</option>
                    <option value="owner">Owner (full access)</option>
                  </select>
                </div>
                <div><Label>PIN {editId && <span className="text-xs text-muted-foreground">(blank = keep)</span>}</Label><Input data-testid="staff-pin" value={form.pin} onChange={(e) => setForm({ ...form, pin: e.target.value })} maxLength={4} placeholder="4 digits" /></div>
              </div>
              <div className="grid grid-cols-2 gap-3">
                <div><Label>Phone</Label><Input value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })} /></div>
                <div><Label>Email</Label><Input value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })} /></div>
              </div>
            </div>
            <DialogFooter><Button onClick={save} data-testid="save-staff-btn">Save</Button></DialogFooter>
          </DialogContent>
        </Dialog>
      </div>

      <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
        {staff.filter((s) => s.active).map((s) => (
          <Card key={s.id} className="p-5 hoverable" data-testid={`staff-card-${s.id}`}>
            <div className="flex items-center gap-3">
              <Avatar className="w-14 h-14">
                <AvatarImage src={s.photo_url ? (s.photo_url.startsWith("http") ? s.photo_url : fileUrl(s.photo_url)) : undefined} />
                <AvatarFallback>{s.name?.[0]}</AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <h3 className="font-semibold truncate">{s.name}</h3>
                <Badge className={`${roleColor(s.role)} hover:${roleColor(s.role)} capitalize text-[10px]`}>{s.role}</Badge>
              </div>
            </div>
            <div className="mt-3 space-y-1 text-sm text-muted-foreground">
              <p>ID: <span className="font-mono">{s.staff_id}</span></p>
              {s.phone && <p className="flex items-center gap-1.5"><Phone className="w-3.5 h-3.5" />{s.phone}</p>}
            </div>
            <div className="flex gap-2 mt-3">
              <Button size="sm" variant="outline" onClick={() => edit(s)} data-testid={`edit-staff-${s.id}`}><Pencil className="w-4 h-4 mr-1" /> Edit</Button>
              {s.role !== "owner" && <Button size="sm" variant="ghost" className="text-rose-500" onClick={() => del(s.id)}><Trash2 className="w-4 h-4" /></Button>}
            </div>
          </Card>
        ))}
      </div>
    </div>
  );
}
