import React, { useEffect, useState } from "react";
import { api, errMsg } from "@/lib/api";
import { useAuth } from "@/context/AuthContext";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Checkbox } from "@/components/ui/checkbox";
import { Badge } from "@/components/ui/badge";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger, DialogFooter } from "@/components/ui/dialog";
import { Plus, ClipboardList, Trash2, X, Printer } from "lucide-react";
import { toast } from "sonner";

export default function Prep() {
  const { user, isManager } = useAuth();
  const [items, setItems] = useState([]);
  const [recipes, setRecipes] = useState([]);
  const [open, setOpen] = useState(false);
  const empty = { name: "", qty: "", unit: "", station: "", done: false, best_before: "", portions: "", allergens: [], recipe_id: "", date: new Date().toISOString().slice(0, 10) };
  const [form, setForm] = useState(empty);

  const load = () => {
    api.get("/prep").then((r) => setItems(r.data)).catch(() => {});
    api.get("/recipes").then((r) => setRecipes(r.data)).catch(() => {});
  };
  useEffect(() => { load(); }, []);

  const onRecipe = (rid) => {
    const r = recipes.find((x) => x.id === rid);
    if (!r) { setForm((f) => ({ ...f, recipe_id: "" })); return; }
    const bb = r.shelf_life_days ? new Date(Date.now() + Number(r.shelf_life_days) * 86400000).toISOString().slice(0, 10) : "";
    setForm((f) => ({ ...f, recipe_id: rid, name: r.name, unit: r.yield_unit || f.unit, portions: r.yield_qty ?? f.portions, allergens: r.allergens || [], best_before: bb || f.best_before }));
  };

  const [signTask, setSignTask] = useState(null);
  const [signQty, setSignQty] = useState("");
  const openSign = (t) => { setSignTask(t); setSignQty(String(t.qty ?? "")); };
  const undo = async (t) => { await api.put(`/prep/${t.id}`, { done: false, done_by: "", done_qty: "", done_at: "" }); load(); };
  const confirmSign = async () => {
    await api.put(`/prep/${signTask.id}`, { done: true, done_by: user.name, done_qty: signQty, done_at: new Date().toISOString() });
    toast.success("Prep signed off"); setSignTask(null); load();
  };

  const save = async () => { if (!form.name) return toast.error("Add a task"); try { await api.post("/prep", form); setOpen(false); setForm(empty); load(); } catch (e) { toast.error(errMsg(e)); } };
  const del = async (id) => { await api.delete(`/prep/${id}`); load(); };
  const bin = async (t) => {
    try { await api.post(`/prep/${t.id}/waste`, {}); toast.success(`${t.name} binned → logged to wastage`); load(); }
    catch (e) { toast.error(errMsg(e)); }
  };

  const printLabel = (t) => {
    const today = new Date().toLocaleDateString();
    const allerg = (t.allergens || []).join(", ") || "None";
    const w = window.open("", "_blank", "width=380,height=520");
    if (!w) return toast.error("Allow pop-ups to print labels");
    w.document.write(`<html><head><title>${t.name} label</title><style>
      body{font-family:Arial,Helvetica,sans-serif;padding:20px;color:#0f172a}
      h1{font-size:22px;margin:0 0 10px} .row{margin:6px 0;font-size:15px}
      .bb{color:#b91c1c;font-weight:bold;font-size:17px} .lab{color:#64748b;font-size:12px}
      .foot{margin-top:16px;font-size:11px;color:#94a3b8;border-top:1px solid #eee;padding-top:8px}
    </style></head><body>
      <h1>${t.name}</h1>
      <div class="row"><span class="lab">Portions kept:</span> <b>${t.portions || t.done_qty || t.qty || "—"} ${t.unit || ""}</b></div>
      <div class="row"><span class="lab">Prepared:</span> ${today}${t.done_by ? " by " + t.done_by : ""}</div>
      <div class="row bb">Best before: ${t.best_before || "—"}</div>
      <div class="row"><span class="lab">Allergens:</span> ${allerg}</div>
      <div class="foot">CulinaryPulse · ${t.station || "Kitchen"}</div>
    </body></html>`);
    w.document.close(); w.focus(); w.print();
  };

  const stations = [...new Set(items.map((i) => i.station || "General"))];

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between flex-wrap gap-3">
        <div>
          <h1 className="text-3xl font-bold tracking-tight flex items-center gap-2"><ClipboardList className="w-7 h-7 text-primary" /> Prep List</h1>
          <p className="text-muted-foreground">Today's mise en place, by station.</p>
        </div>
        {isManager && (
          <Dialog open={open} onOpenChange={(v) => { setOpen(v); if (!v) setForm(empty); }}>
            <DialogTrigger asChild><Button data-testid="add-prep-btn"><Plus className="w-4 h-4 mr-1" /> Add task</Button></DialogTrigger>
            <DialogContent className="max-h-[90vh] overflow-y-auto">
              <DialogHeader><DialogTitle>Add prep task</DialogTitle></DialogHeader>
              <div className="space-y-3">
                <div><Label>From recipe (optional — auto-fills best-before &amp; allergens)</Label>
                  <select data-testid="prep-recipe" className="w-full h-10 rounded-md border px-3 mt-1 bg-background" value={form.recipe_id} onChange={(e) => onRecipe(e.target.value)}>
                    <option value="">— none —</option>
                    {recipes.map((r) => <option key={r.id} value={r.id}>{r.name}{r.shelf_life_days ? ` (${r.shelf_life_days}d)` : ""}</option>)}
                  </select>
                </div>
                <div><Label>Task</Label><Input data-testid="prep-name" value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })} /></div>
                <div className="grid grid-cols-3 gap-3">
                  <div><Label>Qty</Label><Input value={form.qty} onChange={(e) => setForm({ ...form, qty: e.target.value })} /></div>
                  <div><Label>Unit</Label><Input value={form.unit} onChange={(e) => setForm({ ...form, unit: e.target.value })} /></div>
                  <div><Label>Station</Label><Input value={form.station} onChange={(e) => setForm({ ...form, station: e.target.value })} /></div>
                </div>
                <div className="grid grid-cols-2 gap-3">
                  <div><Label>Best before</Label><Input type="date" data-testid="prep-bb" value={form.best_before} onChange={(e) => setForm({ ...form, best_before: e.target.value })} /></div>
                  <div><Label>Portions kept</Label><Input data-testid="prep-portions" value={form.portions} onChange={(e) => setForm({ ...form, portions: e.target.value })} placeholder="e.g. 12" /></div>
                </div>
                {form.allergens?.length > 0 && <div className="flex flex-wrap gap-1">{form.allergens.map((a) => <Badge key={a} className="bg-rose-100 text-rose-700 hover:bg-rose-100 text-[10px]">{a}</Badge>)}</div>}
              </div>
              <DialogFooter><Button onClick={save} data-testid="save-prep-btn">Save</Button></DialogFooter>
            </DialogContent>
          </Dialog>
        )}
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {stations.map((st) => (
          <Card key={st} className="p-4">
            <h3 className="font-semibold mb-3">{st}</h3>
            <div className="space-y-2">
              {items.filter((i) => (i.station || "General") === st).map((t) => (
                <div key={t.id} className="flex items-start gap-3 py-1.5 group" data-testid={`prep-${t.id}`}>
                  <Checkbox className="mt-0.5" checked={!!t.done} onCheckedChange={() => (t.done ? undo(t) : openSign(t))} data-testid={`prep-check-${t.id}`} />
                  <div className="flex-1">
                    <div className={t.done ? "line-through text-muted-foreground" : ""}>
                      <span className="text-sm font-medium">{t.name}</span>
                      {t.qty && <span className="text-xs text-muted-foreground ml-2">{t.qty} {t.unit}</span>}
                    </div>
                    {t.done && t.done_by && !t.wasted && <p className="text-[11px] text-emerald-600 mt-0.5">✓ {t.done_qty || t.qty} {t.unit} done by {t.done_by}</p>}
                    {t.wasted && <p className="text-[11px] text-rose-600 mt-0.5">🗑 Binned → wastage by {t.done_by}</p>}
                    {t.best_before && !t.wasted && (() => {
                      const today = new Date().toISOString().slice(0, 10);
                      const tmr = new Date(Date.now() + 86400000).toISOString().slice(0, 10);
                      const cls = t.best_before <= today ? "bg-rose-100 text-rose-700" : t.best_before === tmr ? "bg-amber-100 text-amber-700" : "bg-slate-100 text-slate-600";
                      const label = t.best_before <= today ? "Use today (last day)" : t.best_before === tmr ? "Use by tomorrow" : `Best before ${t.best_before}`;
                      return <span className={`inline-block mt-1 text-[11px] px-1.5 py-0.5 rounded ${cls}`}>{label}{t.portions ? ` · ${t.portions} ${t.unit || "portions"} kept` : ""}</span>;
                    })()}
                    {(t.allergens || []).length > 0 && <div className="flex flex-wrap gap-1 mt-1">{t.allergens.map((a) => <Badge key={a} className="bg-rose-50 text-rose-600 hover:bg-rose-50 text-[9px] px-1 py-0">{a}</Badge>)}</div>}
                  </div>
                  {isManager && (
                    <div className="flex items-center gap-0.5 opacity-100 sm:opacity-0 sm:group-hover:opacity-100">
                      <button onClick={() => printLabel(t)} title="Print label" data-testid={`label-${t.id}`} className="p-1 text-slate-400 hover:text-primary"><Printer className="w-4 h-4" /></button>
                      {!t.wasted && <button onClick={() => bin(t)} title="Bin unused → wastage" data-testid={`bin-${t.id}`} className="p-1 text-slate-400 hover:text-amber-600"><Trash2 className="w-4 h-4" /></button>}
                      <button onClick={() => del(t.id)} title="Remove task" className="p-1 text-slate-400 hover:text-rose-500"><X className="w-4 h-4" /></button>
                    </div>
                  )}
                </div>
              ))}
            </div>
          </Card>
        ))}
      </div>

      <Dialog open={!!signTask} onOpenChange={(v) => !v && setSignTask(null)}>
        <DialogContent>
          <DialogHeader><DialogTitle>Sign off prep task</DialogTitle></DialogHeader>
          {signTask && (
            <div className="space-y-3">
              <p className="text-sm font-medium">{signTask.name}</p>
              <div><Label>How much did you actually do?</Label>
                <div className="flex gap-2 mt-1">
                  <Input data-testid="sign-qty" value={signQty} onChange={(e) => setSignQty(e.target.value)} placeholder="Quantity" />
                  <div className="h-10 px-3 grid place-items-center rounded-md border bg-secondary text-sm text-muted-foreground">{signTask.unit || "units"}</div>
                </div>
              </div>
              <p className="text-xs text-muted-foreground">Signed off by <b>{user.name}</b></p>
            </div>
          )}
          <DialogFooter><Button onClick={confirmSign} data-testid="confirm-sign-btn">Mark done</Button></DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
